// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

abstract contract FlagChallenge {
    string public challengeName;
    string private rewardFlag;
    mapping(address => bool) public solved;

    event FlagClaimed(address indexed player, string challengeName, string flag);

    constructor(string memory name_, string memory flag_) {
        challengeName = name_;
        rewardFlag = flag_;
    }

    function claimFlag() external returns (string memory) {
        require(!solved[msg.sender], "already solved");
        require(_isSolved(msg.sender), "challenge not solved");

        solved[msg.sender] = true;
        emit FlagClaimed(msg.sender, challengeName, rewardFlag);
        return rewardFlag;
    }

    function getFlagAfterSolved() external view returns (string memory) {
        require(solved[msg.sender], "not solved");
        return rewardFlag;
    }

    function _isSolved(address player) internal view virtual returns (bool);
}

contract EasyAccessControl is FlagChallenge {
    address public owner;
    mapping(address => bool) public passed;

    constructor(string memory flag_) FlagChallenge("EasyAccessControl", flag_) {
        owner = msg.sender;
    }

    function changeOwner(address newOwner) external {
        owner = newOwner;
    }

    function openDoor() external {
        require(msg.sender == owner, "not owner");
        passed[msg.sender] = true;
    }

    function _isSolved(address player) internal view override returns (bool) {
        return passed[player];
    }
}
